from datetime import datetime, timedelta
from google.cloud import monitoring_v3
from google.api import metric_pb2
from google.protobuf.timestamp_pb2 import Timestamp
from observability_client import get_gcp_monitoring_client
from observability_models import MetricQuery, Datapoint

def query_metric_window(
    project_id: str,
    metric_query: MetricQuery,
    end_time: datetime = None,
    window_minutes: int = 60
) -> list[Datapoint]:
    client = get_gcp_monitoring_client()
    project_name = f"projects/{project_id}"

    if end_time is None:
        end_time = datetime.now()
    start_time = end_time - timedelta(minutes=window_minutes)

    interval = monitoring_v3.TimeInterval(
        end_time=Timestamp(seconds=int(end_time.timestamp())),
        start_time=Timestamp(seconds=int(start_time.timestamp())),
    )

    results = client.list_time_series(
        name=project_name,
        filter=f'metric.type = "{metric_query.metric_type}" AND resource.type = "{metric_query.resource_type}"',
        interval=interval,
        view=monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
    )

    datapoints = []
    for series in results:
        for point in series.points:
            datapoints.append(Datapoint(
                timestamp=point.interval.end_time.ToDatetime(),
                value=point.value.double_value if point.value.HasField('double_value') else point.value.int64_value
            ))
    return datapoints",
