def aggregate_metric_stats(
    namespace: str,
    metric_query: MetricQuery,
    end_time: datetime = None,
    window_minutes: int = 60,
    period_seconds: int = 60,
    statistics: list[str] = None
) -> MetricStatistics:
    cloudwatch = get_aws_client('cloudwatch')

    if end_time is None:
        end_time = datetime.now()
    start_time = end_time - timedelta(minutes=window_minutes)

    if statistics is None:
        statistics = ['Average'] # Default to Average

    dimensions = []
    if metric_query.dimensions:
        for dim_name, dim_value in metric_query.dimensions.items():
            dimensions.append({'Name': dim_name, 'Value': dim_value})

    response = cloudwatch.get_metric_statistics(
        Namespace=namespace,
        MetricName=metric_query.metric_name,
        Dimensions=dimensions,
        StartTime=start_time,
        EndTime=end_time,
        Period=period_seconds,
        Statistics=statistics
    )

    stats_data = {}
    if response and 'Datapoints' in response:
        for stat_type in statistics:
            values = [dp[stat_type] for dp in response['Datapoints'] if stat_type in dp]
            if values:
