  "filter_metric_dimensions.py": "import os
from datetime import datetime, timedelta
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient
from observability_client import get_azure_monitor_client
from observability_models import MetricQuery, Datapoint

def filter_metric_dimensions(
    resource_id: str,
    metric_query: MetricQuery,
    end_time: datetime = None,
    window_minutes: int = 60
) -> list[Datapoint]:
    client = get_azure_monitor_client()

    if end_time is None:
        end_time = datetime.now()
    start_time = end_time - timedelta(minutes=window_minutes)

    timespan = f"{start_time.isoformat()}/{end_time.isoformat()}"

    # Azure Monitor queries are powerful, supporting OData filters
    # For this example, we build a filter based on dimensions
    odata_filter = None
    if metric_query.dimensions:
        filter_parts = []
        for dim_name, dim_value in metric_query.dimensions.items():
            filter_parts.append(f"{dim_name} eq '{dim_value}'")
        odata_filter = " and ".join(filter_parts)

    response = client.query_resource(
        resource_id=resource_id,
        metric_names=[metric_query.metric_name],
        timespan=timespan,
        interval="PT1M", # 1 minute interval
        filter=odata_filter, 
        granularity=timedelta(minutes=1)
    )

    datapoints = []
    for metric in response.metrics:
        for time_series in metric.timeseries:
            for data_point in time_series.data:
                if data_point.average is not None:
                    datapoints.append(Datapoint(timestamp=data_point.timestamp, value=data_point.average))
                elif data_point.total is not None:
                    datapoints.append(Datapoint(timestamp=data_point.timestamp, value=data_point.total))

    return datapoints",
