from datetime import datetime, timedelta
from datadog_api_client.v1 import ApiClient, Configuration
from datadog_api_client.v1.api.metrics_api import MetricsApi
from observability_client import get_datadog_client_config
from observability_models import MetricQuery, Datapoint, ComparisonResult

def compare_metric_series(
    metric_query_1: MetricQuery,
    metric_query_2: MetricQuery,
    end_time: datetime = None,
    window_minutes: int = 60
) -> ComparisonResult:
    config = get_datadog_client_config()

    if end_time is None:
        end_time = datetime.now()
    start_time = end_time - timedelta(minutes=window_minutes)

    query_string_1 = f"{metric_query_1.metric_name}"
    if metric_query_1.dimensions:
        tag_parts = [f"{k}:{v}" for k, v in metric_query_1.dimensions.items()]
        query_string_1 = f"{query_string_1}{{{''.join(tag_parts)}}}"

    query_string_2 = f"{metric_query_2.metric_name}"
    if metric_query_2.dimensions:
        tag_parts = [f"{k}:{v}" for k, v in metric_query_2.dimensions.items()]
        query_string_2 = f"{query_string_2}{{{''.join(tag_parts)}}}"

    with ApiClient(config) as api_client:
        metrics_api = MetricsApi(api_client)

        series1_response = metrics_api.query_metrics(
            from_=int(start_time.timestamp()),
            to=int(end_time.timestamp()),
            query=query_string_1
        )

        series2_response = metrics_api.query_metrics(
            from_=int(start_time.timestamp()),
            to=int(end_time.timestamp()),
            query=query_string_2
        )

    series1_data = []
    if series1_response.series:
        for series in series1_response.series:
            for point in series.pointlist:
                series1_data.append(Datapoint(timestamp=datetime.fromtimestamp(point[0]/1000), value=point[1]))

    series2_data = []
    if series2_response.series:
        for series in series2_response.series:
            for point in series.pointlist:
                series2_data.append(Datapoint(timestamp=datetime.fromtimestamp(point[0]/1000), value=point[1]))

    # Basic comparison: sum of values for simplicity
    sum1 = sum(dp.value for dp in series1_data if dp.value is not None)
    sum2 = sum(dp.value for dp in series2_data if dp.value is not None)

    comparison_description = "Series 1 is greater than Series 2" if sum1 > sum2 else \
                             "Series 2 is greater than Series 1" if sum2 > sum1 else \
                             "Series 1 and Series 2 are equal (based on sum)"

    return ComparisonResult(
        query1_name=metric_query_1.metric_name,
        query2_name=metric_query_2.metric_name,
        data1=series1_data,
        data2=series2_data,
        comparison_summary=comparison_description
    )",
