from observability_client import get_openai_client
from observability_models import MetricSummary, Datapoint

def summarize_metric_trends(
    metric_name: str,
    datapoints: list[Datapoint],
    summary_length: str = "short"
) -> MetricSummary:
    client = get_openai_client()

    if not datapoints:
        return MetricSummary(metric_name=metric_name, summary_text="No data available.", anomaly_detected=False)

    # Prepare data for the prompt
    datapoint_strings = [f"Time: {dp.timestamp}, Value: {dp.value}" for dp in datapoints]
    data_excerpt = "\n".join(datapoint_strings[-20:]) # Last 20 datapoints

    prompt = f"""
Analyze the following metric data for '{metric_name}'. Provide a {summary_length} summary of recent trends, identify any noticeable anomalies, and state if the trend is generally increasing, decreasing, or stable.

Metric Name: {metric_name}
Recent Data Points:
{data_excerpt}

Summary:
"""

    response = client.chat.completions.create(
        model="gpt-4o-mini", # Using a concrete model ID
        messages=[
            {"role": "system", "content": "You are a helpful assistant that analyzes metric data."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=200
    )

    summary_text = response.choices[0].message.content.strip()

    # Basic attempt to extract trend and anomaly for the MetricSummary object
    trend = 'stable'
    anomaly_detected = 'anomaly' in summary_text.lower() or 'unusual' in summary_text.lower()

    if 'increasing' in summary_text.lower():
        trend = 'increasing'
    elif 'decreasing' in summary_text.lower():
        trend = 'decreasing'

    return MetricSummary(
        metric_name=metric_name,
        summary_text=summary_text,
        trend=trend,
        anomaly_detected=anomaly_detected
    )",
