from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import TextCategory,
                                            TextAnalyzeSeverity,
                                            AnalyzeTextOptions,
                                            TextBlocklistMatchResult
from observability_client import get_azure_content_safety_client
from observability_models import AnnotationSafetyResult

def check_annotation_safety(
    annotation_text: str
) -> AnnotationSafetyResult:
    client = get_azure_content_safety_client()

    categories = [
        TextCategory.HATE,
        TextCategory.VIOLENCE,
        TextCategory.SELF_HARM,
        TextCategory.SEXUAL
    ]

    request = AnalyzeTextOptions(
        text=annotation_text,
        categories=categories,
        blocklist_names=[] # You can specify blocklists here if configured
    )

    response = client.analyze_text(request)

    is_safe = True
    moderation_details = {}
    for category in response.categories_analysis:
        moderation_details[category.category.value] = {
            'severity': category.severity,
            'detected': category.severity > 0
        }
        if category.severity > 0: # A severity greater than 0 indicates detected unsafe content
            is_safe = False

    if response.blocklist_matches:
        blocklist_matches = []
        for match in response.blocklist_matches:
            blocklist_matches.append({
                'blocklist_name': match.blocklist_name,
                'block_item_text': match.block_item_text,
                'block_item_id': match.block_item_id
            })
        moderation_details['blocklist_matches'] = blocklist_matches
        is_safe = False

    return AnnotationSafetyResult(
        text=annotation_text,
        is_safe=is_safe,
        moderation_details=moderation_details
    )",
