from datetime import datetime
from google.cloud import storage
from observability_client import get_gcp_storage_client
from observability_models import ArchiveResult

def archive_metrics_snapshot(
    bucket_name: str,
    filename: str,
    data_bytes: bytes,
    content_type: str = 'application/json'
) -> ArchiveResult:
    client = get_gcp_storage_client()

    bucket = client.bucket(bucket_name)
    blob = bucket.blob(filename)

    blob.upload_from_string(data_bytes, content_type=content_type)

    # Refresh blob attributes to get updated info like size, time_created
    blob.reload()

    return ArchiveResult(
        filename=filename,
        bucket_name=bucket_name,
        uri=f"gs://{bucket_name}/{filename}",
        size_bytes=blob.size,
        timestamp=blob.time_created
    )",
